/**
 * DEMO STUB — in the real app this file already exists
 * (src/components/survey-history/repositories/detail-reported.ts) and calls
 * POST /api/survey/report/generate/<survey_id>/ { language } → { pdf_url }.
 * Here it returns a sample 21-page report generated by the local backend.
 */
export interface DetailReportResponse {
    pdf_url: string;
}

export class DetailReportedRepository {
    async generateDetailReport(_reportId: string, _options?: { language?: string; timeout?: number }): Promise<DetailReportResponse> {
        await new Promise((resolve) => setTimeout(resolve, 600));
        return { pdf_url: "/sample/detail-report-sample.pdf" };
    }
}

export default DetailReportedRepository;
